"css": "/* =============================================================================\n     サイドバーのスクロールバーを非表示にする\n     （スクロールの操作自体は通常通り可能です）\n     ============================================================================= */\n\n  /* Firefox 向け */\n  .notion-sidebar-container .notion-scroller,\n  .notion-sidebar .notion-scroller,\n  nav .notion-scroller {\n    scrollbar-width: none !important;\n  }\n\n  /* Chrome / Safari / Edge 向け */\n  .notion-sidebar-container .notion-scroller::-webkit-scrollbar,\n  .notion-sidebar .notion-scroller::-webkit-scrollbar,\n  nav .notion-scroller::-webkit-scrollbar {\n    display: none !important;\n    width: 0 !important;\n    height: 0 !important;\n  }\n/* =============================================================================\n   16c 幕 ─ v1.1.0 ／ 貼り付け先: Stylus（« No »　¹⁸ _ Screen Curtain を置き換え）\n   -----------------------------------------------------------------------------\n   v1.0.9 まで: すりガラス（半透明 50% ＋ ぼかし 6px）\n     → 向こうが透けるので、並び替え・位置合わせ・書体の切り替わりが「動き」として見えていた。\n   v1.1.0:\n     ・幕は不透明（Notion の地の色と同じ色）。描き直しは一切見えない\n     ・読み込み中の合図は、画面上端の細い線がゆっくり流れるだけ（控えめ）\n     ・開く時は「幕が消える」のではなく、地の色から中身が静かに浮かび上がるフェード\n     ・JS（16c Screen Curtain v1.5.0）が「本当に整い終わった」合図（data-c16c-open=\"1\"）を出すまで開かない\n     ・保険の強制オープンは 20 秒のまま\n\n   調整する数字は「ここをいじって調整」の中だけです。\n   ============================================================================= */\n\n:root {\n  /* ───── ここをいじって調整 ─────────────────────────────────────────── */\n\n  /* ① 幕の色（Notion の地の色に合わせる。ずれると開く瞬間に色が変わって見える） */\n  --c16c-bg-light: #ffffff;\n  --c16c-bg-dark:  #191919;\n\n  /* ② 幕の不透明度（1 = 何も見えない。すりガラスに戻すなら .5 前後＋③） */\n  --c16c-alpha: 1;\n\n  /* ③ ぼかし（不透明なら効果は無い。すりガラスに戻す時だけ 6px など） */\n  --c16c-blur: 0px;\n\n  /* ④ 開く時のフェードの長さ */\n  --c16c-fade: .28s;\n\n  /* ⑤ 読み込み中の線（0 で消す） */\n  --c16c-bar-height: 2px;\n  --c16c-bar-color-light: rgba(55, 53, 47, .16);\n  --c16c-bar-color-dark:  rgba(255, 255, 255, .14);\n\n  /* ──────────────────────────────────────────────────────────────── */\n  --c16c-bg: var(--c16c-bg-light);\n  --c16c-bar: var(--c16c-bar-color-light);\n}\n\n/* ダークテーマ（Notion の印・OS の設定のどちらでも） */\nhtml.dark, html[data-theme=\"dark\"], html:has(> body.dark), html:has(> body.notion-dark-theme) {\n  --c16c-bg: var(--c16c-bg-dark);\n  --c16c-bar: var(--c16c-bar-color-dark);\n}\n@media (prefers-color-scheme: dark) {\n  html:not(:has(> body.notion-light-theme)) {\n    --c16c-bg: var(--c16c-bg-dark);\n    --c16c-bar: var(--c16c-bar-color-dark);\n  }\n}\n\n/* ---------- 幕 ---------- */\nhtml::before {\n  content: '';\n  position: fixed;\n  inset: 0;\n  z-index: 2147483000;\n  pointer-events: none;                 /* 操作は妨げない（見せるだけ） */\n  background: var(--c16c-bg);\n  opacity: var(--c16c-alpha);\n  -webkit-backdrop-filter: blur(var(--c16c-blur));\n  backdrop-filter: blur(var(--c16c-blur));\n  transition: opacity var(--c16c-fade) cubic-bezier(.2, 0, 0, 1), visibility 0s linear var(--c16c-fade);\n  visibility: visible;\n}\n\n/* ---------- 読み込み中: ぶりが泳ぐ（v2.3 — 0.7 秒より長くかかる時だけ、真ん中で小さく） ---------- */\nhtml::after {\n  content: \"('-' 鰤)з\";\n  position: fixed;\n  top: 50%;\n  left: 50%;\n  z-index: 2147483001;\n  pointer-events: none;\n  padding: 7px 14px;\n  border-radius: 999px;\n  font: 500 14px/1.2 \"Hiragino Maru Gothic ProN\", \"Zen Maru Gothic\", \"M PLUS Rounded 1c\", \"Hiragino Sans\", sans-serif;\n  letter-spacing: 0;\n  color: var(--c16c-fish, rgba(55, 53, 47, .62));\n  background: var(--c16c-fish-bg, rgba(55, 53, 47, .05));\n  white-space: nowrap;\n  transform: translate(-50%, -50%);\n  opacity: 0;\n  animation: c16c-fish-in .5s ease .7s forwards, c16c-swim 2.6s cubic-bezier(.45, 0, .55, 1) .7s infinite;\n  transition: opacity .2s ease, visibility 0s linear .2s;\n  visibility: visible;\n}\nhtml[data-c39-dark]::after { --c16c-fish: rgba(255, 255, 255, .62); --c16c-fish-bg: rgba(255, 255, 255, .06); }\n@keyframes c16c-fish-in { to { opacity: 1; } }\n@keyframes c16c-swim {\n  0%, 100% { transform: translate(calc(-50% - 22px), -50%) rotate(-2deg); }\n  25%      { transform: translate(-50%, calc(-50% - 5px)) rotate(0deg); }\n  50%      { transform: translate(calc(-50% + 22px), -50%) rotate(2deg); }\n  75%      { transform: translate(-50%, calc(-50% + 4px)) rotate(0deg); }\n}\n\n/* ---------- 開く ---------- */\nhtml[data-c16c-open=\"1\"]::before {\n  opacity: 0;\n  visibility: hidden;\n}\nhtml[data-c16c-open=\"1\"]::after {\n  opacity: 0;\n  visibility: hidden;\n  animation: none;\n}\n\n/* 保険（v2.2）: 16c の JS が動いていない時（印が無い）は 2.5 秒、動いている時（印が \"0\"）は 9 秒で必ず開く。\n   v2.1 は 3 秒で必ず開いていたため、読み込みに 4 秒かかる端末では JS の合図より先に開き、描き直しが見えていた */\nhtml:not([data-c16c-open])::before {\n  animation: c16c-lift 1ms linear 2.5s forwards;\n}\nhtml[data-c16c-open=\"0\"]::before {\n  animation: c16c-lift 1ms linear 9s forwards;\n}\n@keyframes c16c-lift { to { opacity: 0; visibility: hidden; } }\n\n@media (prefers-reduced-motion: reduce) {\n  html::before { transition: none; }\n  html::after { animation: c16c-fish-in .3s ease .7s forwards; }\n}",
